    "Add your business details": "完善您的企业信息",
    "Add your catalog in the Products tab, or ring up a one-off item below.": "在“产品”标签页添加商品目录，或在下方直接结算单次商品。",
    "All caught up": "已处理完所有事项",
    "All clear": "一切正常",
    "Company name": "企业名称",
    "Create a PDF": "创建a PDF",
    "Create a base from a CSV file.": "创建a base from a CSV file.",
    "Create a base from scratch, start from a template, or import a spreadsheet.": "创建a base from scratch, start from a template, or import a spreadsheet.",
