    "Create my first project": "创建my first project",
    "Create new": "新建",
    "Create survey": "创建survey",
    "Create your first invoice or estimate. It takes about a minute.": "创建your first invoice or estimate. It takes about a minute.",
    "Create your help desk": "创建your help desk",
